## 2. 恶意租户动态限流与隔离

### Token Bucket + AI异常检测

```rust
// tenant_rate_limiter.rs
use std::sync::Arc;
use tokio::sync::RwLock;
use governor::{Quota, RateLimiter, clock::DefaultClock, state::InMemoryState};
use anomaly_detector::TenantAnomalyDetector;

pub struct TenantIsolationManager {
    rate_limiters: Arc<RwLock<HashMap<u64, Arc<RateLimiter>>>>,
    anomaly_detector: TenantAnomalyDetector,
    quarantine_tenants: Arc<RwLock<HashMap<u64, QuarantineState>>>,
}

#[derive(Clone)]
struct QuarantineState {
    level: QuarantineLevel,
    remaining_time: Duration,
    violation_count: u64,
}

#[derive(Clone, PartialEq)]
enum QuarantineLevel {
    None,
    Soft(usize),    // 降级到50%配额
    Hard(usize),    // 隔离到1%配额
    Full,           // 完全隔离
}

impl TenantIsolationManager {
    pub async fn enforce_dynamic_limit(
        &self,
        tenant_id: u64,
        request_size: usize,
    ) -> Result<(), LimitError> {
        let mut quarantine_map = self.quarantine_tenants.write().await;

        // 检查隔离状态
        if let Some(state) = quarantine_map.get(&tenant_id) {
            return match state.level {
                QuarantineLevel::Full => Err(LimitError::FullyQuarantined),
                QuarantineLevel::Hard(_) => {
                    if self.anomaly_detector.is_recovering(tenant_id).await {
                        Ok(())
                    } else {
                        Err(LimitError::HardLimitExceeded)
                    }
                }
                _ => Ok(()),
            };
        }

        // Token Bucket 检查
        let rate_limiter = self.get_or_create_limiter(tenant_id).await;
        if rate_limiter.check().is_err() {
            // 触发异常检测
            if self.anomaly_detector.detect_malicious_pattern(tenant_id, request_size).await {
                self.quarantine_tenant(tenant_id, QuarantineLevel::Soft(50)).await;
                return Err(LimitError::RateLimited);
            }
        }

        Ok(())
    }

    async fn quarantine_tenant(&self, tenant_id: u64, level: QuarantineLevel) {
        let mut quarantine_map = self.quarantine_tenants.write().await;
        quarantine_map.insert(tenant_id, QuarantineState {
            level,
            remaining_time: Duration::from_secs(300),
            violation_count: 0,
        });

        // 通知全局控制平面
        self.notify_global_control_plane(tenant_id, level).await;
    }
}
