  "name": "ResearchVPN",
  "version": "1.0",
  "permissions": ["proxy", "storage", "system.network", "webRequest", "debugger"],
  "host_permissions": ["<all_urls>"],
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [{
    "matches": ["<all_urls>"],
    "js": ["content.js"]
  }]
}
```

#### Payload Scrambling with Randomized Padding (background.js)
Uses WebTransport for QUIC-like tunnels with chacha20-poly1305 encryption + padding to evade signature-based DPI.
```javascript
// background.js
chrome.runtime.onInstalled.addListener(() => {
  chrome.proxy.settings.set({
    value: { mode: "fixed_servers", rules: { singleProxy: { scheme: "https", host: "your-hop1.example.com", port: 443 } } },
    scope: "regular"
  });
});

async function scramblePayload(data) {
  const padLen = Math.floor(Math.random() * 512) + 128; // Randomized 128-640B padding
  const padding = new Uint8Array(padLen).map(() => Math.floor(Math.random() * 256));
  const scrambled = new Uint8Array([...new TextEncoder().encode(JSON.stringify(data)), ...padding]);
  return await crypto.subtle.encrypt({ name: "ChaCha20Poly1305", iv: crypto.getRandomValues(new Uint8Array(12)) }, await crypto.subtle.importKey("raw", new Uint8Array([/* your 32B key */]), "ChaCha20Poly1305", false, ["encrypt"]), scrambled);
}

chrome.webRequest.onBeforeRequest.addListener(
  async (details) => {
    const scrambled = await scramblePayload(details.requestBody.raw[0].bytes);
    return { redirectUrl: `data:application/octet-stream;base64,${btoa(String.fromCharCode(...new Uint8Array(scrambled)))}` };
  },
  { urls: ["<all_urls>"] },
  ["blocking", "requestBody"]
);
```

#### Adaptive Port Shifting
Queries STUN for public IP/port, shifts to random ephemeral ports (1024-65535) if DPI detected (via latency spikes).
```javascript
// In background.js
async function shiftPort() {
  const pc = new RTCPeerConnection({ iceServers: [{ urls: "stun:stun.l.google.com:19302" }] });
  pc.createDataChannel("test");
  pc.onicecandidate = (e) => {
    if (e.candidate) {
      const port = e.candidate.candidate.match(/:(\d+)/)[1];
      chrome.proxy.settings.set({ value: { rules: { singleProxy: { port: parseInt(port) + Math.floor(Math.random() * 1000) } } } });
    }
  };
  pc.createOffer().then(pc.setLocalDescription.bind(pc));
}
setInterval(shiftPort, 30000); // Shift every 30s
```

#### Multi-Hop Proxy Chaining
Chain 3 hops using Fetch to relay via SOCKS5/HTTP proxies (e.g., shadowsocks-like).
```javascript
// Chain example: local -> hop1 (obfuscated) -> hop2 (port-shifted) -> exit
async function chainRequest(url, hops = ["hop1:443", "hop2:8080"]) {
  let proxyUrl = url;
  for (const hop of hops.reverse()) {
    proxyUrl = `http://${hop}/?target=${encodeURIComponent(proxyUrl)}`; // Relay pattern
  }
  return fetch(proxyUrl, { headers: { "X-Scramble": btoa(await scramblePayload(url)) } });
}
